// ─── HOOQ Ads Agent — Config ─────────────────────────────────────────────────
// Lee el payload del webhook y prepara las variables para los 4 scrapers.
// NOTA: el token de Apify se lee desde process.env.APIFY_TOKEN
// Configurar en Railway → Variables: APIFY_TOKEN=tu_token

const body = $('Webhook').item.json.body || $('Webhook').item.json;

const keyword   = body.keyword || '';
const encodedKw = encodeURIComponent(keyword);

const fbAdsUrl = `https://www.facebook.com/ads/library/?active_status=active&ad_type=all&country=ALL&q=${encodedKw}&search_type=keyword_unordered&media_type=video`;
const igAdsUrl = fbAdsUrl + '&publisher_platforms[0]=instagram';

return [{
  json: {
    keyword,
    countries:        body.countries || ['ALL'],
    maxAds:           body.max_ads || 30,
    minViews:         body.filters?.min_views || 100000,
    minDuration:      body.filters?.min_duration_seconds || 15,
    maxAgeDays:       body.filters?.max_age_days || 90,
    minDaysActive:    body.filters?.min_days_active || 7,
    platforms:        body.filters?.platforms || ['facebook', 'instagram', 'tiktok', 'ig_organic'],
    dna_expert:       body.dna_expert || '',
    dna_audience:     body.dna_audience || '',
    dna_product:      body.dna_product || '',
    telegram_chat_id: body.telegram_chat_id || '',
    email:            body.email || '',
    fbAdsUrl,
    igAdsUrl,
  }
}];

// ─── Scraper: Facebook Ads Library ──────────────────────────────────────────
const config = $('Config').item.json;
const apifyToken = process.env.APIFY_TOKEN || '';

if (!apifyToken) {
  return [{ json: { _platform: 'facebook', _error: 'APIFY_TOKEN no configurado' } }];
}

let items = [];
try {
  const results = await this.helpers.httpRequest({
    method: 'POST',
    url: `https://api.apify.com/v2/acts/apify~facebook-ads-scraper/run-sync-get-dataset-items?token=${apifyToken}&timeout=120`,
    body: {
      startUrls: [{ url: config.fbAdsUrl }],
      maxItems: config.maxAds || 30,
      country: 'ALL',
      activeStatus: 'active',
      sortOrder: 'relevancy_monthly_grouped'
    },
    json: true,
    timeout: 180000
  });
  items = Array.isArray(results) ? results : [];
  console.log(`FB Ads: ${items.length} obtenidos`);
} catch(e) {
  console.log('FB Ads error:', e.message);
}

return items.length > 0 ? items.map(ad => ({ json: ad })) : [{ json: { _platform: 'facebook', _empty: true } }];

// ─── Scraper: Instagram Ads Library (paid) ───────────────────────────────────
const config = $('Config').item.json;
const apifyToken = process.env.APIFY_TOKEN || '';

if (!apifyToken) {
  return [{ json: { _platform: 'instagram_ads', _error: 'APIFY_TOKEN no configurado' } }];
}

let items = [];
try {
  const results = await this.helpers.httpRequest({
    method: 'POST',
    url: `https://api.apify.com/v2/acts/apify~facebook-ads-scraper/run-sync-get-dataset-items?token=${apifyToken}&timeout=120`,
    body: {
      startUrls: [{ url: config.igAdsUrl }],
      maxItems: config.maxAds || 30,
      country: 'ALL',
      activeStatus: 'active',
      sortOrder: 'relevancy_monthly_grouped'
    },
    json: true,
    timeout: 180000
  });
  items = Array.isArray(results) ? results : [];
  console.log(`IG Ads: ${items.length} obtenidos`);
} catch(e) {
  console.log('IG Ads error:', e.message);
}

return items.length > 0 ? items.map(ad => ({ json: ad })) : [{ json: { _platform: 'instagram_ads', _empty: true } }];

// ─── Scraper: TikTok orgánico ────────────────────────────────────────────────
const config = $('Config').item.json;
const apifyToken = process.env.APIFY_TOKEN || '';

if (!apifyToken) {
  return [{ json: { _platform: 'tiktok', _error: 'APIFY_TOKEN no configurado' } }];
}

let items = [];
try {
  const results = await this.helpers.httpRequest({
    method: 'POST',
    url: `https://api.apify.com/v2/acts/clockworks~free-tiktok-scraper/run-sync-get-dataset-items?token=${apifyToken}&timeout=120`,
    body: {
      hashtags: [config.keyword],
      resultsPerPage: config.maxAds || 30,
      maxItems: config.maxAds || 30
    },
    json: true,
    timeout: 180000
  });
  items = Array.isArray(results) ? results : [];
  console.log(`TikTok: ${items.length} obtenidos`);
} catch(e) {
  console.log('TikTok error:', e.message);
}

return items.length > 0 ? items.map(v => ({ json: v })) : [{ json: { _platform: 'tiktok', _empty: true } }];

// ─── Scraper: Instagram orgánico por hashtag ─────────────────────────────────
// Actor: apify/instagram-hashtag-scraper
// Scrapeamos posts por hashtag de la keyword — mismas reglas que TikTok:
// views >= 100K, duración >= 15s, antigüedad <= 90 días

const config = $('Config').item.json;
const apifyToken = process.env.APIFY_TOKEN || '';

if (!apifyToken) {
  return [{ json: { _platform: 'ig_organic', _error: 'APIFY_TOKEN no configurado' } }];
}

// Limpiar keyword para usarla como hashtag (sin espacios, sin #)
const hashtag = config.keyword.replace(/\s+/g, '').replace(/^#/, '');

let items = [];
try {
  const results = await this.helpers.httpRequest({
    method: 'POST',
    url: `https://api.apify.com/v2/acts/apify~instagram-hashtag-scraper/run-sync-get-dataset-items?token=${apifyToken}&timeout=120`,
    body: {
      hashtags: [hashtag],
      resultsLimit: config.maxAds || 30
    },
    json: true,
    timeout: 180000
  });
  items = Array.isArray(results) ? results : [];
  console.log(`IG Orgánico: ${items.length} posts obtenidos para #${hashtag}`);
} catch(e) {
  console.log('IG Orgánico error:', e.message);
}

return items.length > 0 ? items.map(p => ({ json: p })) : [{ json: { _platform: 'ig_organic', _empty: true } }];

// ─── Filtro: Facebook Ads — proxy = días activo ───────────────────────────────
const items = $input.all();
const config = $('Config').item.json;
const minDaysActive = config.minDaysActive || 7;
const maxAgeDays    = config.maxAgeDays || 90;
const filtered = [];

for (const item of items) {
  if (item.json._empty || item.json._error) continue;
  const ad = item.json;
  const startDate = ad.startDate || ad.ad_delivery_start_time || ad.start_date || ad.adDeliveryStartTime;
  let daysActive = 0;
  if (startDate) {
    daysActive = Math.floor((Date.now() - new Date(startDate).getTime()) / 86400000);
  }
  if (daysActive >= minDaysActive && daysActive <= maxAgeDays) {
    const quality = daysActive >= 30 ? 'high' : daysActive >= 14 ? 'medium' : 'low';
    filtered.push({ json: { ...ad, _daysActive: daysActive, _platform: 'facebook', _qualitySignal: quality, _adText: ad.adText || ad.ad_creative_bodies?.[0] || ad.body || '', _adLink: ad.adUrl || ad.ad_snapshot_url || '' } });
  }
}

filtered.sort((a, b) => (b.json._daysActive || 0) - (a.json._daysActive || 0));
const top = filtered.slice(0, 15);
console.log(`FB Ads filtrados: ${top.length}/${items.length}`);
return top.length > 0 ? top : [{ json: { _platform: 'facebook', _empty: true, _filtered: true } }];

// ─── Filtro: Instagram Ads — proxy = días activo ─────────────────────────────
const items = $input.all();
const config = $('Config').item.json;
const minDaysActive = config.minDaysActive || 7;
const maxAgeDays    = config.maxAgeDays || 90;
const filtered = [];

for (const item of items) {
  if (item.json._empty || item.json._error) continue;
  const ad = item.json;
  const startDate = ad.startDate || ad.ad_delivery_start_time || ad.start_date || ad.adDeliveryStartTime;
  let daysActive = 0;
  if (startDate) {
    daysActive = Math.floor((Date.now() - new Date(startDate).getTime()) / 86400000);
  }
  if (daysActive >= minDaysActive && daysActive <= maxAgeDays) {
    const quality = daysActive >= 30 ? 'high' : daysActive >= 14 ? 'medium' : 'low';
    filtered.push({ json: { ...ad, _daysActive: daysActive, _platform: 'instagram_ads', _qualitySignal: quality, _adText: ad.adText || ad.ad_creative_bodies?.[0] || ad.body || '', _adLink: ad.adUrl || ad.ad_snapshot_url || '' } });
  }
}

filtered.sort((a, b) => (b.json._daysActive || 0) - (a.json._daysActive || 0));
const top = filtered.slice(0, 15);
console.log(`IG Ads filtrados: ${top.length}/${items.length}`);
return top.length > 0 ? top : [{ json: { _platform: 'instagram_ads', _empty: true, _filtered: true } }];

// ─── Filtro: TikTok — views + duración + antigüedad ──────────────────────────
const items = $input.all();
const config = $('Config').item.json;
const MIN_VIEWS    = config.minViews    || 100000;
const MIN_DURATION = config.minDuration || 15;
const MAX_AGE_DAYS = config.maxAgeDays  || 90;
const filtered = [];

for (const item of items) {
  if (item.json._empty || item.json._error) continue;
  const v = item.json;
  const views    = v.playCount || v.plays || v.viewCount || v.stats?.playCount || 0;
  const duration = v.duration  || v.videoLength || v.videoDuration || v.video?.duration || 0;
  const ct = v.createTime || v.createdAt || v.publishedAt;
  let ageInDays = 0;
  if (ct) {
    const created = new Date(typeof ct === 'number' ? ct * 1000 : ct);
    ageInDays = Math.floor((Date.now() - created.getTime()) / 86400000);
  }
  if (views >= MIN_VIEWS && duration >= MIN_DURATION && ageInDays <= MAX_AGE_DAYS && ageInDays > 0) {
    const quality = views >= 1000000 ? 'high' : views >= 500000 ? 'medium' : 'low';
    filtered.push({ json: { ...v, _views: views, _duration: duration, _ageInDays: ageInDays, _platform: 'tiktok', _qualitySignal: quality, _adText: v.text || v.desc || v.description || '', _adLink: v.webVideoUrl || v.shareUrl || '' } });
  }
}

filtered.sort((a, b) => (b.json._views || 0) - (a.json._views || 0));
const top = filtered.slice(0, 15);
console.log(`TikTok filtrados: ${top.length}/${items.length}`);
return top.length > 0 ? top : [{ json: { _platform: 'tiktok', _empty: true, _filtered: true } }];

// ─── Filtro: Instagram orgánico — mismas reglas que TikTok ───────────────────
// views >= 100K, duración >= 15s (solo videos), antigüedad <= 90 días

const items = $input.all();
const config = $('Config').item.json;
const MIN_VIEWS    = config.minViews    || 100000;
const MIN_DURATION = config.minDuration || 15;
const MAX_AGE_DAYS = config.maxAgeDays  || 90;
const filtered = [];

for (const item of items) {
  if (item.json._empty || item.json._error) continue;
  const p = item.json;

  // Métricas de IG orgánico (campos varían según actor de Apify)
  const views    = p.videoViewCount || p.videoPlayCount || p.playCount || p.likesCount || 0;
  const duration = p.videoDuration  || p.video?.duration || p.duration || 0;
  const isVideo  = p.type === 'Video' || p.isVideo || !!p.videoUrl || duration > 0;

  const timestamp = p.timestamp || p.takenAt || p.taken_at || p.createdAt;
  let ageInDays = 0;
  if (timestamp) {
    const created = new Date(typeof timestamp === 'number' ? timestamp * 1000 : timestamp);
    ageInDays = Math.floor((Date.now() - created.getTime()) / 86400000);
  }

  // Solo videos: exigir duración >= 15s y views >= 100K
  // Imágenes/carousels: exigir likes >= 5K (proxy de alcance)
  const likes = p.likesCount || p.likeCount || 0;
  const passesFilter = isVideo
    ? (views >= MIN_VIEWS && duration >= MIN_DURATION)
    : (likes >= 5000);

  if (passesFilter && ageInDays <= MAX_AGE_DAYS && ageInDays > 0) {
    const quality = isVideo
      ? (views >= 1000000 ? 'high' : views >= 500000 ? 'medium' : 'low')
      : (likes >= 50000 ? 'high' : likes >= 10000 ? 'medium' : 'low');

    filtered.push({
      json: {
        ...p,
        _views:         views,
        _duration:      duration,
        _ageInDays:     ageInDays,
        _isVideo:       isVideo,
        _platform:      'ig_organic',
        _qualitySignal: quality,
        _adText:        p.caption || p.text || p.description || '',
        _adLink:        p.url || p.shortCode ? `https://www.instagram.com/p/${p.shortCode}/` : '',
      }
    });
  }
}

filtered.sort((a, b) => (b.json._views || 0) - (a.json._views || 0));
const top = filtered.slice(0, 15);
console.log(`IG Orgánico filtrados: ${top.length}/${items.length}`);
return top.length > 0 ? top : [{ json: { _platform: 'ig_organic', _empty: true, _filtered: true } }];

// ─── Preparar Resumen — 4 plataformas ────────────────────────────────────────
const items = $input.all();
const config = $('Config').item.json;

const summary = {
  facebook:     { total: 0, high: 0, medium: 0, low: 0 },
  instagram_ads:{ total: 0, high: 0, medium: 0, low: 0 },
  tiktok:       { total: 0, high: 0, medium: 0, low: 0 },
  ig_organic:   { total: 0, high: 0, medium: 0, low: 0 },
};

const validContents = [];

for (const item of items) {
  if (item.json._empty || item.json._error || item.json._filtered) continue;
  const platform = item.json._platform || 'unknown';
  const quality  = item.json._qualitySignal || 'low';
  if (summary[platform]) {
    summary[platform].total++;
    if (summary[platform][quality] !== undefined) summary[platform][quality]++;
  }
  validContents.push({
    platform,
    quality,
    text:       item.json._adText || '',
    link:       item.json._adLink || '',
    daysActive: item.json._daysActive || 0,
    views:      item.json._views || 0,
    raw:        item.json,
  });
}

const total = validContents.length;

const summaryText =
  `📊 *Contenidos encontrados para "${config.keyword}"*\n\n` +
  `• FB Ads: ${summary.facebook.total} (${summary.facebook.high} alta calidad)\n` +
  `• IG Ads: ${summary.instagram_ads.total} (${summary.instagram_ads.high} alta calidad)\n` +
  `• TikTok: ${summary.tiktok.total} (${summary.tiktok.high} alta calidad)\n` +
  `• IG Orgánico: ${summary.ig_organic.total} (${summary.ig_organic.high} alta calidad)\n\n` +
  `✅ *Total seleccionados para modelar: ${total}*\n` +
  `_Iniciando pipeline de modelado con tu DNA..._`;

console.log(`Resumen: ${total} contenidos válidos de 4 plataformas`);

return [{
  json: {
    contents:         validContents,
    summary,
    summaryText,
    totalContents:    total,
    keyword:          config.keyword,
    dna_expert:       config.dna_expert,
    dna_audience:     config.dna_audience,
    dna_product:      config.dna_product,
    telegram_chat_id: config.telegram_chat_id,
    email:            config.email,
  }
}];
